/*
 * timestamp.c
 *		Functions for the SQL "timestamp" and "interval" types.
 *
 * Portions Copyright (c) 1996-2019, PostgreSQL Global Development Group
 * Portions Copyright (c) 1994, Regents of the University of California
 *
