 */
#include "postgres.h"

#include <ctype.h>
#include <time.h>
#include <math.h>

#include "access/hash.h"
#include "catalog/pg_type.h"
#include "common/int.h"
#include "datatype/timestamp.h"
#include "fmgr.h"
#include "funcapi.h"
#include "lib/stringinfo.h"
#include "nodes/nodeFuncs.h"
#include "utils/array.h"
#include "utils/builtins.h"
#include "utils/date.h"
#include "utils/datetime.h"
#include "utils/numeric.h"
#include "utils/sampling.h"
#include "utils/timestamp.h"
#include "utils/typcache.h"


/*
 * date_trunc
 *		Truncate a timestamp to the specified unit.
 *
 * Syntax: date_trunc(unit, timestamp)
 * Returns: timestamp truncated to the specified unit
 *
 * Supported units: year, month, day, hour, minute, second
 */
PG_FUNCTION_INFO_V1(date_trunc);

Datum
date_trunc(PG_FUNCTION_ARGS)
{
	text	   *unit_text = PG_GETARG_TEXT_P(0);
	Timestamp	ts = PG_GETARG_TIMESTAMP(1);
	char	   *unit_str;
	Timestamp	result;
	struct pg_tm tm;
	fsec_t		fsec;
	int			tz;

	/* Convert unit string to lowercase for comparison */
	unit_str = text_to_cstring(unit_text);
	for (int i = 0; unit_str[i]; i++)
		unit_str[i] = pg_tolower((unsigned char) unit_str[i]);

	/* Handle NULL timestamp early */
	if (TIMESTAMP_IS_NOBEGIN(ts) || TIMESTAMP_IS_NOEND(ts))
	{
		pfree(unit_str);
		PG_RETURN_TIMESTAMP(ts);
	}

	/* Convert timestamp to broken-down time */
	if (timestamp2tm(ts, NULL, &tm, &fsec, NULL, NULL) != 0)
		ereport(ERROR,
				(errcode(ERRCODE_DATETIME_VALUE_OUT_OF_RANGE),
				 errmsg("timestamp out of range")));

	/* Truncate based on unit */
	if (strcmp(unit_str, "year") == 0)
	{
		tm.tm_mon = 1;			/* January */
		tm.tm_mday = 1;			/* 1st day */
		tm.tm_hour = 0;
		tm.tm_min = 0;
		tm.tm_sec = 0;
		fsec = 0;
	}
	else if (strcmp(unit_str, "month") == 0)
	{
		tm.tm_mday = 1;			/* 1st day */
		tm.tm_hour = 0;
		tm.tm_min = 0;
		tm.tm_sec = 0;
		fsec = 0;
	}
	else if (strcmp(unit_str, "day") == 0)
	{
		tm.tm_hour = 0;
		tm.tm_min = 0;
		tm.tm_sec = 0;
		fsec = 0;
	}
	else if (strcmp(unit_str, "hour") == 0)
	{
		tm.tm_min = 0;
		tm.tm_sec = 0;
		fsec = 0;
	}
	else if (strcmp(unit_str, "minute") == 0)
	{
		tm.tm_sec = 0;
		fsec = 0;
	}
	else if (strcmp(unit_str, "second") == 0)
	{
		fsec = 0;
	}
	else
	{
		pfree(unit_str);
		ereport(ERROR,
				(errcode(ERRCODE_INVALID_PARAMETER_VALUE),
				 errmsg("unit \"%s\" not supported for date_trunc", unit_str),
				 errhint("Valid units are: year, month, day, hour, minute, second.")));
	}

	/* Convert back to timestamp */
	if (tm2timestamp(&tm, fsec, NULL, &ts) != 0)
		ereport(ERROR,
				(errcode(ERRCODE_DATETIME_VALUE_OUT_OF_RANGE),
				 errmsg("timestamp out of range")));

	pfree(unit_str);
	PG_RETURN_TIMESTAMP(ts);
}

